+const nextPlugin = require('@next/eslint-plugin-next')
+
+function createReportProxy(context, mapMessage) {
+  const proxy = Object.create(context)
+
+  proxy.report = function (descriptor, ...arguments_) {
+    if (descriptor && typeof descriptor === 'object' && typeof descriptor.message === 'string') {
+      return context.report({
+        ...descriptor,
+        message: mapMessage(descriptor.message)
+      })
+    }
+
+    return context.report(descriptor, ...arguments_)
+  }
+
+  return proxy
+}
+
+function wrapNextRule(ruleName, mapMessage) {
+  const rule = nextPlugin.rules[ruleName]
+
+  if (typeof rule === 'function') {
+    nextPlugin.rules[ruleName] = Object.assign(function (context) {
+      return rule(createReportProxy(context, mapMessage))
+    }, rule)
+
+    return
+  }
+
+  nextPlugin.rules[ruleName] = {
+    ...rule,
+    create(context) {
+      return rule.create(createReportProxy(context, mapMessage))
+    }
+  }
+}
+
+wrapNextRule('no-css-tags', message => message === 'Do not include stylesheets manually. See: https://nextjs.org/docs/messages/no-css-tags.' ? 'In order to use external stylesheets use @import in the root stylesheet compiled with NextJS. This ensures proper priority to CSS when loading a webpage.' : message)
